export function applySettings(settings){const s=document.documentElement.style;s.setProperty('--textscale',settings.textSize/14);s.setProperty('--accent',settings.accent);s.setProperty('--codesize',settings.codeSize+'px');s.setProperty('--textsize',settings.textSize+'px');document.body.classList.toggle('theme-dim',settings.theme==='dim');document.body.classList.toggle('reduce-motion',settings.reducedMotion)}
export function playFeedback(enabled,correct){if(!enabled)return;try{const Audio=window.AudioContext||window.webkitAudioContext;const ctx=new Audio();const osc=ctx.createOscillator(),gain=ctx.createGain();osc.frequency.value=correct?620:260;gain.gain.setValueAtTime(.035,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.1);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.12);osc.onended=()=>ctx.close()}catch{}}
